insert into public.units (id, level_id, title, description, position, published) values
  ('7577b15a-50fe-4498-b438-9944ddae0b4c', '534b108a-3d62-011b-bf3b-91f75fa7c7e1', 'Greetings and introductions', 'Say hello, say goodbye and tell people who you are.', 1, true),
  ('2ae22fa8-3463-d41f-30a9-791f9fa21f03', '534b108a-3d62-011b-bf3b-91f75fa7c7e1', 'Food and drink', 'Order at a café and in a restaurant.', 2, true),
  ('a70a674a-3ca4-d574-6c88-e7271e6dcc10', 'f47d2998-ef00-8cf7-cd18-0ec4363cc78f', 'Salutations', 'Greet people and introduce yourself.', 1, true),
  ('c22ee9b1-45db-2acf-d6aa-7c17a62ce5aa', 'f47d2998-ef00-8cf7-cd18-0ec4363cc78f', 'At the café', 'Order a drink and something to eat.', 2, true),
  ('3c524989-b8e6-b2a4-f465-3914d03f4875', 'd6221d0c-1037-ddbc-fc63-09426f53c177', 'Greetings', 'Say hello, thank people and tell them your name.', 1, true)
insert into public.lessons (id, unit_id, title, description, grammar_note, estimated_minutes, position, published) values
  ('c2a58fc8-1270-eb48-75ec-1f9cc3f40932', '7577b15a-50fe-4498-b438-9944ddae0b4c', 'Hello and goodbye', 'The greetings you will use every single day.', 'Spanish greets by time of day: buenos días (morning), buenas tardes (afternoon until early evening) and buenas noches (evening and night). Notice that días is masculine plural and tardes/noches are feminine plural, so the greeting changes its ending.', 6, 1, true),
  ('55f498b1-7745-1c6d-cb13-3edd29e655b1', '7577b15a-50fe-4498-b438-9944ddae0b4c', 'Introducing yourself', 'Say your name and where you are from.', 'To say your name use me llamo (literally “I call myself”). To say where you are from use soy de (“I am from”). Soy comes from the verb ser: yo soy, tú eres, él/ella es.', 7, 2, true),
  ('313fc597-d532-05c3-742a-c023cff89163', '2ae22fa8-3463-d41f-30a9-791f9fa21f03', 'At the café', 'Order a drink and a snack politely.', 'Spanish nouns have gender. Most nouns ending in -o are masculine (un bocadillo) and most ending in -a are feminine (una limonada). Words like café and té are masculine, so they take un. Quisiera (“I would like”) is a polite way to ask for something.', 7, 1, true),
  ('fb04736a-e45d-43db-54db-35ded9322bdd', '2ae22fa8-3463-d41f-30a9-791f9fa21f03', 'Ordering a meal', 'Say you are hungry and order food.', 'To say you are hungry or thirsty Spanish uses tener (to have): tengo hambre, tengo sed. Literally “I have hunger” and “I have thirst”. Yo tengo → tengo; tú tienes → tienes; él/ella tiene → tiene.', 8, 2, true),
  ('507640c4-eb49-ccc3-4ba9-09bbfc9626ef', 'a70a674a-3ca4-d574-6c88-e7271e6dcc10', 'Bonjour!', 'Greetings and polite words.', 'Use bonjour during the day and bonsoir in the evening. Salut is informal, for friends. French also has two ways to say “you”: tu (informal) and vous (polite or plural), so s''il vous plaît is the polite “please” and s''il te plaît is the friendly one.', 6, 1, true),
  ('38e9e2c7-41f1-0bf2-dd4f-7866c2e2f7c5', 'a70a674a-3ca4-d574-6c88-e7271e6dcc10', 'Introductions', 'Say who you are and where you are from.', 'Je m''appelle means “my name is” (literally “I call myself”). Je suis de means “I am from”. Suis comes from être: je suis, tu es, il/elle est.', 7, 2, true),
  ('6e64a7d9-030e-524a-b200-9baf569df5ec', 'c22ee9b1-45db-2acf-d6aa-7c17a62ce5aa', 'Au café', 'Order politely in a French café.', 'French nouns are masculine or feminine: un café, un croissant, une eau. Je voudrais (“I would like”) is the polite way to order. Before a vowel, le and la become l'': l''eau, l''addition.', 7, 1, true),
  ('7941c143-5ba6-3d2d-3d45-9cdc8bb6d8c8', '3c524989-b8e6-b2a4-f465-3914d03f4875', 'नमस्ते: first greetings', 'Greet people and answer politely.', 'Hindi sentences put the verb at the end: मेरा नाम प्रिया है (“My name Priya is”). है (hai) means “is”. The polite “you” is आप (aap), which takes the verb form हैं (hain): आप कैसे हैं?', 7, 1, true)
insert into public.exercises (id, lesson_id, type, skill, prompt, instructions, explanation, audio_url, content, position) values
  ('2abfe24b-291d-a7b8-5416-90537bdc08a1', 'c2a58fc8-1270-eb48-75ec-1f9cc3f40932', 'multiple_choice', 'vocabulary', 'How do you say “good morning” in Spanish?', 'Choose the correct answer.', 'Buenos días is used in the morning. Buenas noches is for the evening and night.', null, '{}'::jsonb, 1),
  ('3588f600-4105-1880-6e4b-a14672987e4a', 'c2a58fc8-1270-eb48-75ec-1f9cc3f40932', 'matching', 'vocabulary', 'Match each word with its meaning.', 'Tap a word on the left, then its match on the right.', 'Hola opens a conversation, adiós and hasta luego close it, and gracias thanks someone.', null, '{}'::jsonb, 2),
  ('7b465900-ab22-5ea4-0050-3806ac46fb96', 'c2a58fc8-1270-eb48-75ec-1f9cc3f40932', 'listening', 'listening', 'What did you hear?', 'Press play, listen, then choose the answer. You can replay it as often as you like.', 'Buenas noches is said in the evening and when going to bed.', null, '{"speak":"Buenas noches"}'::jsonb, 3),
  ('a2a3e41c-b0ad-3c2e-5474-ac4eacc7f88f', 'c2a58fc8-1270-eb48-75ec-1f9cc3f40932', 'translation', 'writing', 'Thank you', 'Translate into Spanish.', 'Gracias means thank you. Muchas gracias adds “very much”.', null, '{"accepted":["gracias","muchas gracias"]}'::jsonb, 4),
  ('6b87965b-d749-ed90-863d-6d951bc95dcd', 'c2a58fc8-1270-eb48-75ec-1f9cc3f40932', 'word_arrangement', 'writing', 'Good afternoon, thank you.', 'Tap the words in the right order to build the sentence.', 'Greeting first, then the thanks: Buenas tardes, gracias.', null, '{"answer":["Buenas","tardes","gracias"],"distractors":["días","adiós"]}'::jsonb, 5),
  ('1a6e41c0-5f9e-e25f-0e07-73b04c9d3c60', 'c2a58fc8-1270-eb48-75ec-1f9cc3f40932', 'fill_blank', 'vocabulary', 'Buenos ___, señora López.', 'Type the missing word.', 'Before midday you say buenos días. Remember the accent on días.', null, '{"accepted":["días"],"meaning":"Good morning, Mrs López."}'::jsonb, 6),
  ('dd794cfe-8c17-dfdf-b5c9-a69fa9d0a921', 'c2a58fc8-1270-eb48-75ec-1f9cc3f40932', 'speaking', 'speaking', 'Greet someone for the morning.', 'Say the phrase out loud. If your browser cannot listen, you can rate yourself instead.', 'Hola is hello and buenos días is good morning. Roll the r lightly in Spanish and say every vowel clearly.', null, '{"target":"Hola, buenos días"}'::jsonb, 7),
  ('2a28a8e6-98bd-34bf-d697-df41862a1be5', 'c2a58fc8-1270-eb48-75ec-1f9cc3f40932', 'reading', 'reading', 'How does Ana answer Luis?', 'Read the text, then answer the question.', '“Muy bien, gracias” means “Very well, thank you”.', null, '{"passage":"Ana: Hola, buenas tardes.\nLuis: Buenas tardes, Ana. ¿Cómo estás?\nAna: Muy bien, gracias.","glossary":{"¿Cómo estás?":"How are you?","muy bien":"very well"}}'::jsonb, 8),
  ('d1ce56ec-16fd-c4e4-cce8-cb973d419503', '55f498b1-7745-1c6d-cb13-3edd29e655b1', 'multiple_choice', 'vocabulary', 'What does “¿Cómo te llamas?” mean?', 'Choose the correct answer.', 'Literally “How do you call yourself?”, which is the usual way to ask someone''s name.', null, '{}'::jsonb, 1),
  ('7ea53956-d565-0dc8-9bde-27e217279f8d', '55f498b1-7745-1c6d-cb13-3edd29e655b1', 'grammar', 'grammar', 'Yo ___ de México.', 'Choose the form that completes the sentence.', 'With yo (I) the verb ser becomes soy: yo soy.', null, '{}'::jsonb, 2),
  ('0f9156ea-4a88-b30d-a8ed-9f3b54d21272', '55f498b1-7745-1c6d-cb13-3edd29e655b1', 'translation', 'writing', 'My name is Sara.', 'Translate into Spanish.', 'Me llamo Sara is the natural way. Mi nombre es is also correct but sounds more formal.', null, '{"accepted":["me llamo Sara","mi nombre es Sara"]}'::jsonb, 3),
  ('3c56c001-ded4-8464-23f6-68cb9e17bf8b', '55f498b1-7745-1c6d-cb13-3edd29e655b1', 'fill_blank', 'grammar', '¿De dónde ___ tú?', 'Type the missing word.', 'With tú (you, informal) the verb ser is eres.', null, '{"accepted":["eres"],"meaning":"Where are you from?"}'::jsonb, 4),
  ('4469d14e-2869-dd8c-6068-ba1284936e1c', '55f498b1-7745-1c6d-cb13-3edd29e655b1', 'word_arrangement', 'writing', 'Nice to meet you, I am Pablo.', 'Tap the words in the right order to build the sentence.', 'Mucho gusto is the greeting, then soy Pablo.', null, '{"answer":["Mucho","gusto","soy","Pablo"],"distractors":["eres","llamas"]}'::jsonb, 5),
  ('79e047f3-7087-b039-3774-83ffa8ea24ac', '55f498b1-7745-1c6d-cb13-3edd29e655b1', 'listening', 'listening', 'What is her name?', 'Press play, listen, then choose the answer. You can replay it as often as you like.', 'Me llamo Carmen means “My name is Carmen”.', null, '{"speak":"Me llamo Carmen"}'::jsonb, 6),
  ('413ffec2-8195-03d7-7107-0c4f134717c1', '55f498b1-7745-1c6d-cb13-3edd29e655b1', 'writing', 'writing', 'Write two or three sentences introducing yourself: your name and where you are from.', 'Write your answer in the language you are learning. Use the suggested words.', 'Start with me llamo plus your name, then soy de plus a place.', null, '{"minWords":4,"keywords":["me llamo","soy de"],"sample":"Me llamo Sara. Soy de la India. Mucho gusto."}'::jsonb, 7),
  ('6dd1b900-84fe-7986-c9ee-ccf6a84a62ed', '55f498b1-7745-1c6d-cb13-3edd29e655b1', 'speaking', 'speaking', 'Introduce yourself out loud.', 'Say the phrase out loud. If your browser cannot listen, you can rate yourself instead.', 'Say me llamo and soy de as smooth groups of sounds. The double l in llamo sounds like a y.', null, '{"target":"Me llamo Ana y soy de España"}'::jsonb, 8),
  ('cadf7eb0-ebf7-b604-a134-a3a7dcad4335', '313fc597-d532-05c3-742a-c023cff89163', 'matching', 'vocabulary', 'Match each word with its meaning.', 'Tap a word on the left, then its match on the right.', 'These are the four drinks you will meet most often on a Spanish café menu.', null, '{}'::jsonb, 1),
  ('8c172a4e-c29d-3bf3-2a64-fed2d6ce3f08', '313fc597-d532-05c3-742a-c023cff89163', 'multiple_choice', 'vocabulary', 'Which word means “bread”?', 'Choose the correct answer.', 'Pan is bread. It is masculine, so it takes el.', null, '{}'::jsonb, 2),
  ('c4476ac5-fb97-f11f-ef0c-fe665668706d', '313fc597-d532-05c3-742a-c023cff89163', 'grammar', 'grammar', '___ limonada, por favor.', 'Choose the form that completes the sentence.', 'Limonada ends in -a and is feminine, so it takes una.', null, '{}'::jsonb, 3),
  ('cdc6246b-e2b1-5add-883f-6c9af533fa0f', '313fc597-d532-05c3-742a-c023cff89163', 'translation', 'writing', 'A coffee, please.', 'Translate into Spanish.', 'Café is masculine, so un café. Por favor means please.', null, '{"accepted":["un café, por favor","un café por favor","quisiera un café","quisiera un café, por favor"]}'::jsonb, 4),
  ('7ba540b8-343a-1c2d-de15-9bd0e435ee01', '313fc597-d532-05c3-742a-c023cff89163', 'listening', 'listening', 'What does the customer want?', 'Press play, listen, then choose the answer. You can replay it as often as you like.', 'Quisiera un té means “I would like a tea”.', null, '{"speak":"Quisiera un té, por favor"}'::jsonb, 5),
  ('183ece6b-db69-df44-5c1d-e51535813458', '313fc597-d532-05c3-742a-c023cff89163', 'fill_blank', 'vocabulary', 'La ___, por favor.', 'Type the missing word.', 'La cuenta is the bill. You ask for it at the end of the meal.', null, '{"accepted":["cuenta"],"meaning":"The bill, please."}'::jsonb, 6),
  ('56faa2ac-e411-fddc-3f60-81d68f273259', '313fc597-d532-05c3-742a-c023cff89163', 'word_arrangement', 'writing', 'I would like a salad.', 'Tap the words in the right order to build the sentence.', 'Ensalada is feminine, so it takes una.', null, '{"answer":["Quisiera","una","ensalada"],"distractors":["un","té"]}'::jsonb, 7),
  ('51ad7591-3923-c739-2adf-5ea3ab6d81b9', '313fc597-d532-05c3-742a-c023cff89163', 'reading', 'reading', 'What does the customer order?', 'Read the text, then answer the question.', 'The customer says un café y un bocadillo: a coffee and a sandwich.', null, '{"passage":"Camarero: Buenas tardes. ¿Qué desea?\nCliente: Quisiera un café y un bocadillo, por favor.\nCamarero: Muy bien.","glossary":{"camarero":"waiter","¿Qué desea?":"What would you like?","muy bien":"very good, fine"}}'::jsonb, 8),
  ('29c50be0-a86f-25b0-6a82-7b38c5fa21d7', '313fc597-d532-05c3-742a-c023cff89163', 'speaking', 'speaking', 'Order a coffee politely.', 'Say the phrase out loud. If your browser cannot listen, you can rate yourself instead.', 'Keep the stress on the é in café. Por favor has the stress on the last syllable.', null, '{"target":"Un café, por favor"}'::jsonb, 9),
  ('479ea2ed-f52a-a20e-3e7e-0c74ea75d4e8', 'fb04736a-e45d-43db-54db-35ded9322bdd', 'multiple_choice', 'vocabulary', 'How do you say “I am hungry”?', 'Choose the correct answer.', 'Spanish uses tener for hunger: tengo hambre, literally “I have hunger”.', null, '{}'::jsonb, 1),
  ('926dd0c2-d506-c9fc-cba5-2e26e3f20bc9', 'fb04736a-e45d-43db-54db-35ded9322bdd', 'grammar', 'grammar', 'Yo ___ sed.', 'Choose the form that completes the sentence.', 'Yo goes with tengo, the first person of tener.', null, '{}'::jsonb, 2),
  ('49ebfda7-5fda-4a9d-1296-d90c007f1bb0', 'fb04736a-e45d-43db-54db-35ded9322bdd', 'matching', 'vocabulary', 'Match each word with its meaning.', 'Tap a word on the left, then its match on the right.', 'Pollo, arroz, sopa and ensalada are common words on any menu.', null, '{}'::jsonb, 3),
  ('b50088af-ba44-31f1-15a0-8d8d67c8b6f5', 'fb04736a-e45d-43db-54db-35ded9322bdd', 'translation', 'writing', 'I would like the chicken.', 'Translate into Spanish.', 'Quisiera is the polite wish. Quiero (“I want”) is also fine and me gustaría (“I would like”) is very polite.', null, '{"accepted":["quisiera el pollo","quiero el pollo","me gustaría el pollo","me gustaria el pollo"]}'::jsonb, 4),
  ('e126f062-7e1e-f9e8-321c-74a5acd40b0c', 'fb04736a-e45d-43db-54db-35ded9322bdd', 'listening', 'listening', 'What is delicious?', 'Press play, listen, then choose the answer. You can replay it as often as you like.', 'La sopa está deliciosa means “The soup is delicious”.', null, '{"speak":"La sopa está deliciosa"}'::jsonb, 5),
  ('03eeccda-ef65-8817-1116-ad3371c0b7a0', 'fb04736a-e45d-43db-54db-35ded9322bdd', 'word_arrangement', 'writing', 'I am thirsty, I would like water.', 'Tap the words in the right order to build the sentence.', 'Say how you feel first (tengo sed) and then what you want (quisiera agua).', null, '{"answer":["Tengo","sed","quisiera","agua"],"distractors":["hambre"]}'::jsonb, 6),
  ('31ad6572-b201-ff08-a7d3-b447c079b1cb', 'fb04736a-e45d-43db-54db-35ded9322bdd', 'fill_blank', 'vocabulary', 'Tengo ___, quisiera una sopa.', 'Type the missing word.', 'Hambre is hunger. Tengo hambre means I am hungry.', null, '{"accepted":["hambre"],"meaning":"I am hungry, I would like a soup."}'::jsonb, 7),
  ('3ae5d887-98ee-be40-0d44-688d47778ee2', 'fb04736a-e45d-43db-54db-35ded9322bdd', 'writing', 'writing', 'Write a short order for the waiter. Say what you would like to eat and drink.', 'Write your answer in the language you are learning. Use the suggested words.', 'Use quisiera for what you would like and finish politely with por favor.', null, '{"minWords":4,"keywords":["quisiera","por favor"],"sample":"Buenas tardes. Quisiera la sopa y agua, por favor."}'::jsonb, 8),
  ('55d6b5db-14b1-a29d-789a-0eb3b168501c', 'fb04736a-e45d-43db-54db-35ded9322bdd', 'speaking', 'speaking', 'Ask for the bill.', 'Say the phrase out loud. If your browser cannot listen, you can rate yourself instead.', 'Say it clearly: la CUEN-ta, por fa-VOR.', null, '{"target":"La cuenta, por favor"}'::jsonb, 9),
  ('258ca33c-d24d-b1a3-da85-433fafd5d84d', '507640c4-eb49-ccc3-4ba9-09bbfc9626ef', 'multiple_choice', 'vocabulary', 'Which greeting is polite for the evening?', 'Choose the correct answer.', 'Bonsoir is the evening greeting. Salut is too casual for a polite situation.', null, '{}'::jsonb, 1),
  ('23866d08-4966-3af4-77f8-6527bd35133c', '507640c4-eb49-ccc3-4ba9-09bbfc9626ef', 'matching', 'vocabulary', 'Match each word with its meaning.', 'Tap a word on the left, then its match on the right.', 'Four of the most useful French words.', null, '{}'::jsonb, 2),
  ('8bf0fe98-dfd5-972b-cfc8-9a6c5a921b61', '507640c4-eb49-ccc3-4ba9-09bbfc9626ef', 'translation', 'writing', 'Thank you very much.', 'Translate into French.', 'Merci is thank you and beaucoup adds “very much”.', null, '{"accepted":["merci beaucoup"]}'::jsonb, 3),
  ('4dc037b3-8e60-85aa-4bc5-ad77b0194729', '507640c4-eb49-ccc3-4ba9-09bbfc9626ef', 'listening', 'listening', 'What did you hear?', 'Press play, listen, then choose the answer. You can replay it as often as you like.', 'Au revoir means goodbye, literally “until we see again”.', null, '{"speak":"Au revoir"}'::jsonb, 4),
  ('0b52c9d5-a32e-9f46-2b47-77aaa26dd622', '507640c4-eb49-ccc3-4ba9-09bbfc9626ef', 'fill_blank', 'grammar', 'S''il ___ plaît, un café.', 'Type the missing word.', 'S''il vous plaît is the polite form and s''il te plaît the informal one.', null, '{"accepted":["vous","te"],"meaning":"A coffee, please."}'::jsonb, 5),
  ('9ba53421-cf51-edcc-5cf3-b2ecafd7d550', '507640c4-eb49-ccc3-4ba9-09bbfc9626ef', 'word_arrangement', 'writing', 'Hello, how are you?', 'Tap the words in the right order to build the sentence.', 'Bonjour, ça va ? is a friendly way to open a chat.', null, '{"answer":["Bonjour","ça","va"],"distractors":["merci","oui"]}'::jsonb, 6),
  ('eff5ef92-acdc-7f57-bea2-82c9b64faa1e', '507640c4-eb49-ccc3-4ba9-09bbfc9626ef', 'speaking', 'speaking', 'Greet someone and thank them.', 'Say the phrase out loud. If your browser cannot listen, you can rate yourself instead.', 'In French the final consonants are often silent: say bonjour as “bon-ZHOOR”.', null, '{"target":"Bonjour, merci beaucoup"}'::jsonb, 7),
  ('988f573f-ffd7-98bb-eda0-5b164015d515', '507640c4-eb49-ccc3-4ba9-09bbfc9626ef', 'reading', 'reading', 'How is Paul?', 'Read the text, then answer the question.', 'Paul says “Ça va bien, merci”: he is doing well.', null, '{"passage":"Marie : Bonjour, Paul ! Ça va ?\nPaul : Oui, ça va bien, merci. Et toi ?\nMarie : Ça va. Au revoir !","glossary":{"et toi ?":"and you?","ça va bien":"it''s going well"}}'::jsonb, 8),
  ('2d993e15-58e8-7185-8467-15bf97c2ecc2', '38e9e2c7-41f1-0bf2-dd4f-7866c2e2f7c5', 'multiple_choice', 'vocabulary', 'What does “Comment tu t''appelles ?” mean?', 'Choose the correct answer.', 'Literally “How do you call yourself?”. It is the informal way to ask someone''s name.', null, '{}'::jsonb, 1),
  ('bdbb2455-5624-b453-1904-794b37a82401', '38e9e2c7-41f1-0bf2-dd4f-7866c2e2f7c5', 'grammar', 'grammar', 'Je ___ de Paris.', 'Choose the form that completes the sentence.', 'With je (I) the verb être becomes suis.', null, '{}'::jsonb, 2),
  ('c56397de-0891-84a4-6113-3aaa469153cf', '38e9e2c7-41f1-0bf2-dd4f-7866c2e2f7c5', 'translation', 'writing', 'My name is Léa.', 'Translate into French.', 'Je m''appelle plus your name. The apostrophe replaces the e of me.', null, '{"accepted":["je m''appelle Léa","je m’appelle Léa","je m''appelle Lea"]}'::jsonb, 3),
  ('c542500a-d491-3d9b-2c35-3258a5f6d7b1', '38e9e2c7-41f1-0bf2-dd4f-7866c2e2f7c5', 'fill_blank', 'grammar', 'Elle ___ française.', 'Type the missing word.', 'With elle (she) the verb être is est.', null, '{"accepted":["est"],"meaning":"She is French."}'::jsonb, 4),
  ('2f9c4c7b-e95a-7f41-687f-2ce9d46a2bde', '38e9e2c7-41f1-0bf2-dd4f-7866c2e2f7c5', 'word_arrangement', 'writing', 'I am from Lyon.', 'Tap the words in the right order to build the sentence.', 'Je suis de followed by the city.', null, '{"answer":["Je","suis","de","Lyon"],"distractors":["es","est"]}'::jsonb, 5),
  ('8f889e86-c823-ecc5-83e1-663582f29261', '38e9e2c7-41f1-0bf2-dd4f-7866c2e2f7c5', 'listening', 'listening', 'What is his name?', 'Press play, listen, then choose the answer. You can replay it as often as you like.', 'Je m''appelle Julien means “My name is Julien”.', null, '{"speak":"Je m''appelle Julien"}'::jsonb, 6),
  ('833eb77c-9102-3b66-82df-0613156e48c5', '38e9e2c7-41f1-0bf2-dd4f-7866c2e2f7c5', 'writing', 'writing', 'Write two or three sentences introducing yourself in French: your name and where you are from.', 'Write your answer in the language you are learning. Use the suggested words.', 'Use je m''appelle for your name and je suis de for your origin.', null, '{"minWords":4,"keywords":["je m''appelle","je suis de"],"sample":"Je m''appelle Sara. Je suis de Londres. Enchantée."}'::jsonb, 7),
  ('c630ec39-23ac-d155-250a-c408f98dd9b3', '38e9e2c7-41f1-0bf2-dd4f-7866c2e2f7c5', 'speaking', 'speaking', 'Introduce yourself out loud.', 'Say the phrase out loud. If your browser cannot listen, you can rate yourself instead.', 'Link je and m''appelle smoothly: “zhuh ma-PELL”.', null, '{"target":"Enchanté, je m''appelle Paul"}'::jsonb, 8),
  ('de81620c-3b9a-c6a9-39dc-f3a51712729d', '6e64a7d9-030e-524a-b200-9baf569df5ec', 'matching', 'vocabulary', 'Match each word with its meaning.', 'Tap a word on the left, then its match on the right.', 'Four basics from a French café menu.', null, '{}'::jsonb, 1),
  ('89eda0ce-fc8b-a548-5d09-2b31b0a83dc7', '6e64a7d9-030e-524a-b200-9baf569df5ec', 'multiple_choice', 'grammar', 'How do you politely order a coffee?', 'Choose the correct answer.', 'Je voudrais means “I would like” and s''il vous plaît makes it polite.', null, '{}'::jsonb, 2),
  ('f36dfa47-8561-837b-3926-47dce796150d', '6e64a7d9-030e-524a-b200-9baf569df5ec', 'grammar', 'grammar', 'Je voudrais ___ croissant.', 'Choose the form that completes the sentence.', 'Croissant is masculine, so it takes un.', null, '{}'::jsonb, 3),
  ('2c5839fc-9e4a-dd7d-306a-d64c2862f18c', '6e64a7d9-030e-524a-b200-9baf569df5ec', 'translation', 'writing', 'A tea, please.', 'Translate into French.', 'Thé is masculine, so un thé. Add s''il vous plaît to be polite.', null, '{"accepted":["un thé, s''il vous plaît","un thé s''il vous plaît","un thé, s''il te plaît","un thé s''il te plaît","je voudrais un thé","je voudrais un thé, s''il vous plaît"]}'::jsonb, 4),
  ('40a55e80-8136-510e-40dd-cc5d5fe0760b', '6e64a7d9-030e-524a-b200-9baf569df5ec', 'listening', 'listening', 'What does the customer ask for?', 'Press play, listen, then choose the answer. You can replay it as often as you like.', 'L''addition is the bill.', null, '{"speak":"L''addition, s''il vous plaît"}'::jsonb, 5),
  ('97a9aa2b-bb03-5d98-0ddd-d1cfdb3be422', '6e64a7d9-030e-524a-b200-9baf569df5ec', 'fill_blank', 'grammar', 'Je ___ un café.', 'Type the missing word.', 'Je voudrais is the polite “I would like”.', null, '{"accepted":["voudrais"],"meaning":"I would like a coffee."}'::jsonb, 6),
  ('6736220e-c08f-488c-8d50-635e1327f458', '6e64a7d9-030e-524a-b200-9baf569df5ec', 'word_arrangement', 'writing', 'I would like a croissant.', 'Tap the words in the right order to build the sentence.', 'Je voudrais + un + the item.', null, '{"answer":["Je","voudrais","un","croissant"],"distractors":["une","suis"]}'::jsonb, 7),
  ('a6ae721b-417a-eafe-4225-20a331e5998f', '6e64a7d9-030e-524a-b200-9baf569df5ec', 'speaking', 'speaking', 'Order a coffee politely.', 'Say the phrase out loud. If your browser cannot listen, you can rate yourself instead.', 'Keep the rhythm even: je vou-DRAIS un ca-FÉ, s''il vous plaît.', null, '{"target":"Je voudrais un café, s''il vous plaît"}'::jsonb, 8),
  ('159eda2c-9b46-cc30-ba07-f870483d0a66', '7941c143-5ba6-3d2d-3d45-9cdc8bb6d8c8', 'multiple_choice', 'vocabulary', 'What does नमस्ते (namaste) mean?', 'Choose the correct answer.', 'नमस्ते is the respectful greeting. It can also be used when leaving.', null, '{"transliteration":"namaste"}'::jsonb, 1),
  ('609e0a90-24e2-cb8c-e0df-8016a1bf75a9', '7941c143-5ba6-3d2d-3d45-9cdc8bb6d8c8', 'matching', 'vocabulary', 'Match each word with its meaning.', 'Tap a word on the left, then its match on the right.', 'धन्यवाद (dhanyavaad), हाँ (haan), नहीं (nahin) and कृपया (kripya).', null, '{}'::jsonb, 2),
  ('7c18f0aa-d3c9-382d-1a63-f1527d425527', '7941c143-5ba6-3d2d-3d45-9cdc8bb6d8c8', 'listening', 'listening', 'What did you hear?', 'Press play, listen, then choose the answer. You can replay it as often as you like.', 'धन्यवाद (dhanyavaad) means thank you.', null, '{"speak":"धन्यवाद"}'::jsonb, 3),
  ('2f387298-0eb9-d9d1-9124-39e8ecd31457', '7941c143-5ba6-3d2d-3d45-9cdc8bb6d8c8', 'translation', 'writing', 'Thank you', 'Translate into Hindi. You may type in Devanagari or in romanised letters.', 'धन्यवाद is the formal thank you. शुक्रिया (shukriya) is a common everyday alternative.', null, '{"accepted":["धन्यवाद","dhanyavaad","dhanyavad","शुक्रिया"],"transliteration":"dhanyavaad"}'::jsonb, 4),
  ('f614e952-73a4-598f-4eab-63130530746c', '7941c143-5ba6-3d2d-3d45-9cdc8bb6d8c8', 'fill_blank', 'vocabulary', 'मेरा ___ प्रिया है।', 'Type the missing word.', 'नाम (naam) means name: मेरा नाम प्रिया है, “My name is Priya”.', null, '{"accepted":["नाम","naam"],"meaning":"My name is Priya."}'::jsonb, 5),
  ('4a95f9a4-4c79-26f2-ab78-d7a8f94726d0', '7941c143-5ba6-3d2d-3d45-9cdc8bb6d8c8', 'word_arrangement', 'writing', 'My name is Priya.', 'Tap the words in the right order to build the sentence.', 'Hindi puts the verb है last: मेरा नाम प्रिया है.', null, '{"answer":["मेरा","नाम","प्रिया","है"],"distractors":["आप","हाँ"]}'::jsonb, 6),
  ('ab93e159-0aec-17ad-0080-f4bea3dcfad4', '7941c143-5ba6-3d2d-3d45-9cdc8bb6d8c8', 'reading', 'reading', 'How is Priya?', 'Read the text, then answer the question.', 'प्रिया says “मैं ठीक हूँ”: I am fine.', null, '{"passage":"राहुल: नमस्ते! आप कैसे हैं?\nप्रिया: मैं ठीक हूँ, धन्यवाद।","glossary":{"कैसे":"how","ठीक":"fine, okay","हूँ":"am"}}'::jsonb, 7),
  ('a4cc5e15-05d0-8fb4-ec86-4319585163f9', '7941c143-5ba6-3d2d-3d45-9cdc8bb6d8c8', 'speaking', 'speaking', 'Greet someone and thank them.', 'Say the phrase out loud. If your browser cannot listen, you can rate yourself instead.', 'Say na-mas-TE and dhan-ya-VAAD. The ध is a breathy d.', null, '{"target":"नमस्ते, धन्यवाद","transliteration":"namaste, dhanyavaad"}'::jsonb, 8)
