  ('1a20af53-fedb-1fac-558b-d4b8cb992b1f', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'hola', 'hello', null, 'interjection', 'A friendly greeting used at any time of day.', '¡Hola! ¿Qué tal?', 'Hello! How''s it going?'),
  ('95e3bb49-f7c2-fa55-c15b-3bb6838748c1', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'buenos días', 'good morning', null, 'phrase', 'Greeting used until around midday.', 'Buenos días, señora.', 'Good morning, madam.'),
  ('cab70bb7-ac60-fbf6-6728-4d9020819867', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'buenas tardes', 'good afternoon', null, 'phrase', 'Greeting used from midday until early evening.', 'Buenas tardes, Luis.', 'Good afternoon, Luis.'),
  ('8c21f7ff-69dd-c6c8-d94e-56f3ae94db5b', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'buenas noches', 'good night', null, 'phrase', 'Evening greeting and the way to say good night.', 'Buenas noches y hasta mañana.', 'Good night and see you tomorrow.'),
  ('6cca816e-74bd-8473-33d1-b13ed34c1450', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'adiós', 'goodbye', null, 'interjection', 'The standard way to say goodbye.', 'Adiós, hasta pronto.', 'Goodbye, see you soon.'),
