  ('45c388f4-a904-5849-cb1f-528715653bbe', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'gracias', 'thank you', null, 'interjection', 'Used to thank someone.', 'Muchas gracias por tu ayuda.', 'Thank you very much for your help.'),
