  ('120cdbfb-f835-cb87-3b82-72b4ac17e274', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'me llamo', 'my name is', null, 'phrase', 'Used to give your name. Literally “I call myself”.', 'Me llamo Carmen.', 'My name is Carmen.'),
  ('a20934ef-c484-aba1-c911-3127ab3e2f2f', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', '¿cómo te llamas?', 'what is your name?', null, 'phrase', 'Informal question to ask someone''s name.', 'Hola, ¿cómo te llamas?', 'Hello, what is your name?'),
  ('9ba380c6-6083-279e-cd7e-0bc45ab2a367', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'soy de', 'I am from', null, 'phrase', 'Used with a country or city to say where you come from.', 'Soy de México.', 'I am from Mexico.'),
  ('879cef56-a88b-0554-99f3-aaaeda1dfa70', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', '¿de dónde eres?', 'where are you from?', null, 'phrase', 'Informal question about someone''s origin.', '¿De dónde eres, Pablo?', 'Where are you from, Pablo?'),
  ('88af0a1c-60c4-d3d0-0400-777684930c8b', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'mucho gusto', 'nice to meet you', null, 'phrase', 'Said when you meet someone for the first time.', 'Mucho gusto, soy Pablo.', 'Nice to meet you, I''m Pablo.'),
  ('67a9c3a0-57ff-9a20-7715-2a5abdb3854a', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'soy', 'I am', null, 'verb', 'First person singular of ser, used for identity and origin.', 'Soy estudiante.', 'I am a student.'),
  ('9fca156f-5da2-70d7-dec0-383c65e9df1e', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'eres', 'you are', null, 'verb', 'Informal singular form of ser.', 'Eres de Chile.', 'You are from Chile.'),
