  ('1fe54a27-d001-969d-e1ca-914b0768fe04', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'el té', 'tea', null, 'noun', 'The drink, masculine in Spanish.', 'Quisiera un té.', 'I would like a tea.'),
