  ('b0f235a3-c6f3-4eb8-de60-fed91d8cb884', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'la leche', 'milk', null, 'noun', 'Feminine noun.', 'El café con leche.', 'Coffee with milk.'),
