  ('e7cddb7a-28dd-988e-d910-bdc5038e3dea', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'la limonada', 'lemonade', null, 'noun', 'A cold drink made with lemon.', 'Una limonada fría.', 'A cold lemonade.'),
  ('7441e3aa-4884-ef53-6ab4-5f3137d20d12', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'quisiera', 'I would like', null, 'verb', 'Polite way to ask for something.', 'Quisiera una ensalada.', 'I would like a salad.'),
