  ('b0cdfaf1-3761-7d38-6a57-cc62ab448218', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'el arroz', 'rice', null, 'noun', 'A staple side dish, masculine.', 'El arroz está bueno.', 'The rice is good.'),
  ('f200fbe3-0aa3-7bb9-394f-7ac4230b14f0', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'la ensalada', 'salad', null, 'noun', 'Cold dish of vegetables.', 'Una ensalada mixta.', 'A mixed salad.'),
  ('5dc61477-5cad-981d-cf73-8864327f873a', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'delicioso', 'delicious', null, 'adjective', 'Describes tasty food. Feminine: deliciosa.', 'La sopa está deliciosa.', 'The soup is delicious.'),
  ('017a90f8-0e6c-4686-bcd7-2d436a0c73bc', 'c2745a9b-6fbe-8efe-bd4c-af59b9ce0fa9', 'el menú', 'the menu', null, 'noun', 'The list of dishes.', 'El menú, por favor.', 'The menu, please.'),
  ('43705481-224c-4bc5-9efa-294071f32d19', '913cf31a-65a3-fb22-bd42-57de298609f4', 'bonjour', 'hello', null, 'interjection', 'Greeting used during the day.', 'Bonjour, madame.', 'Hello, madam.'),
  ('7db8c497-b46b-f492-9008-0364301e3494', '913cf31a-65a3-fb22-bd42-57de298609f4', 'bonsoir', 'good evening', null, 'interjection', 'Greeting used in the evening.', 'Bonsoir, tout le monde.', 'Good evening, everyone.'),
  ('ec941c01-9c88-4e09-e8b0-55a22c7cb5a5', '913cf31a-65a3-fb22-bd42-57de298609f4', 'salut', 'hi', null, 'interjection', 'Informal hello and goodbye.', 'Salut, Paul !', 'Hi, Paul!'),
