  ('3028c043-9337-ddf3-6976-44a07ec1b386', '913cf31a-65a3-fb22-bd42-57de298609f4', 's''il vous plaît', 'please', null, 'phrase', 'Polite “please”.', 'Un café, s''il vous plaît.', 'A coffee, please.'),
  ('dae24317-afc9-c4f7-0253-e928f6009c3e', '913cf31a-65a3-fb22-bd42-57de298609f4', 'oui', 'yes', null, 'adverb', 'Agreeing word.', 'Oui, merci.', 'Yes, thank you.'),
  ('72188f79-116b-b185-dbaa-6de95a0c70fb', '913cf31a-65a3-fb22-bd42-57de298609f4', 'ça va ?', 'how are you?', null, 'phrase', 'Informal “How''s it going?”, also the answer “I''m fine”.', 'Salut, ça va ?', 'Hi, how''s it going?'),
  ('8d798ec5-4f25-d775-16cb-52503191b20a', '913cf31a-65a3-fb22-bd42-57de298609f4', 'je m''appelle', 'my name is', null, 'phrase', 'Used to say your name.', 'Je m''appelle Léa.', 'My name is Léa.'),
