  ('75202c34-5531-2bd7-21da-ffde5701ed00', '913cf31a-65a3-fb22-bd42-57de298609f4', 'elle est', 'she is', null, 'phrase', 'Third person feminine of être.', 'Elle est française.', 'She is French.'),
  ('157f4cdf-10bc-9c78-9e1b-feb78394ad73', '913cf31a-65a3-fb22-bd42-57de298609f4', 'un café', 'a coffee', null, 'noun', 'Masculine noun. In France it usually means a small espresso.', 'Un café, s''il vous plaît.', 'A coffee, please.'),
  ('02473702-c1f3-0ddb-8c26-a19c0c8049c3', '913cf31a-65a3-fb22-bd42-57de298609f4', 'le thé', 'tea', null, 'noun', 'Masculine noun.', 'Je voudrais un thé.', 'I would like a tea.'),
  ('c81fad2f-9a0f-b0bb-af69-4c0a28ea1d13', '913cf31a-65a3-fb22-bd42-57de298609f4', 'l''eau', 'water', null, 'noun', 'Feminine noun, written l''eau.', 'Une carafe d''eau.', 'A jug of water.'),
  ('c453cfab-a0c5-9583-0359-9f61df20c6cd', '913cf31a-65a3-fb22-bd42-57de298609f4', 'le lait', 'milk', null, 'noun', 'Masculine noun.', 'Un café au lait.', 'A coffee with milk.'),
  ('50d77426-df0b-7bb0-3a42-46049740d0a1', '913cf31a-65a3-fb22-bd42-57de298609f4', 'le pain', 'bread', null, 'noun', 'Masculine noun.', 'Du pain, s''il vous plaît.', 'Some bread, please.'),
  ('37485643-318a-0e2b-7eeb-2f8cc986fa74', '913cf31a-65a3-fb22-bd42-57de298609f4', 'un croissant', 'a croissant', null, 'noun', 'A buttery pastry.', 'Un croissant et un café.', 'A croissant and a coffee.'),
  ('d2aa17d0-e422-8238-0333-44c559a27ce4', '913cf31a-65a3-fb22-bd42-57de298609f4', 'je voudrais', 'I would like', null, 'phrase', 'Polite way to order.', 'Je voudrais un croissant.', 'I would like a croissant.'),
  ('53afe771-00dc-58c9-d080-36503949d05d', '913cf31a-65a3-fb22-bd42-57de298609f4', 'l''addition', 'the bill', null, 'noun', 'What you ask for at the end.', 'L''addition, s''il vous plaît.', 'The bill, please.'),
  ('c92e3299-f5e5-5651-6554-dfd67c844554', 'c4c0a2a1-7784-598f-982c-a86756950430', 'नमस्ते', 'hello', 'namaste', 'interjection', 'Respectful greeting, also used for goodbye.', 'नमस्ते, आप कैसे हैं?', 'Hello, how are you?'),
  ('6d09c686-df7a-3c6f-a84c-c8d60b05b392', 'c4c0a2a1-7784-598f-982c-a86756950430', 'धन्यवाद', 'thank you', 'dhanyavaad', 'interjection', 'Formal way to say thank you.', 'आपका बहुत धन्यवाद।', 'Thank you very much.'),
  ('f00935b6-7d16-4cf7-5524-bf08e3c4a227', 'c4c0a2a1-7784-598f-982c-a86756950430', 'कृपया', 'please', 'kripya', 'adverb', 'Used to make a polite request.', 'कृपया बैठिए।', 'Please sit down.'),
  ('25f53ddc-35f7-82f0-7746-c2511f008639', 'c4c0a2a1-7784-598f-982c-a86756950430', 'हाँ', 'yes', 'haan', 'adverb', 'Agreeing word.', 'हाँ, मैं ठीक हूँ।', 'Yes, I am fine.'),
  ('26be6452-fb22-8f72-5eac-27e99b7f6be5', 'c4c0a2a1-7784-598f-982c-a86756950430', 'नहीं', 'no', 'nahin', 'adverb', 'Word for no.', 'नहीं, धन्यवाद।', 'No, thank you.'),
  ('25b9577a-13ba-a993-bf35-8ad3d774a083', 'c4c0a2a1-7784-598f-982c-a86756950430', 'आप कैसे हैं?', 'how are you?', 'aap kaise hain?', 'phrase', 'Polite way to ask how someone is.', 'नमस्ते, आप कैसे हैं?', 'Hello, how are you?'),
  ('5d618b3b-ab80-6910-1480-19eec968e656', 'c4c0a2a1-7784-598f-982c-a86756950430', 'मैं ठीक हूँ', 'I am fine', 'main theek hoon', 'phrase', 'Usual answer to आप कैसे हैं?', 'मैं ठीक हूँ, धन्यवाद।', 'I am fine, thank you.'),
  ('d147d299-60b6-2609-c483-7190cc379c9b', 'c4c0a2a1-7784-598f-982c-a86756950430', 'मेरा नाम', 'my name', 'mera naam', 'phrase', 'Used before your name: मेरा नाम ... है.', 'मेरा नाम प्रिया है।', 'My name is Priya.')
